/** Offline schema scaffold. Never opens a database. */
import { writeFileSync } from "node:fs";
import { getColumns, getTableName, is, SQL } from "drizzle-orm";
import {
	getTableConfig,
	SQLiteDialect,
	SQLiteTable,
} from "drizzle-orm/sqlite-core";
import * as source from "../src/schema/index";

const dialect = new SQLiteDialect();
const tables = Object.entries(source).filter(
	(entry): entry is [string, SQLiteTable] => is(entry[1], SQLiteTable),
);
const lines = [
	"// Generated by scripts/generate-pg-schema.ts. Lane owners review constraints and triggers before moving a domain.",
	'import { sql, getColumns, getTableName } from "drizzle-orm";',
	'import { pgTable, text, jsonb, bigint, boolean, doublePrecision, timestamp, primaryKey, foreignKey, uniqueIndex, index, type AnyPgColumn, type PgTable } from "drizzle-orm/pg-core";',
];
const review: string[] = [];
for (const [name, table] of tables) {
	const config = getTableConfig(table);
	const columns = getColumns(table);
	const keys = new Map(
		Object.entries(columns).map(([key, column]) => [column.name, key]),
	);
	lines.push(
		`export const ${name} = pgTable(${JSON.stringify(config.name)}, {`,
	);
	for (const [key, column] of Object.entries(columns)) {
		const physical = JSON.stringify(column.name);
		const builders: Record<string, string> = {
			SQLiteText: `text(${physical})`,
			SQLiteTextJson: `jsonb(${physical})`,
			SQLiteBoolean: `boolean(${physical})`,
			SQLiteInteger: `bigint(${physical}, { mode: "number" })`,
			SQLiteReal: `doublePrecision(${physical})`,
			SQLiteTimestamp: `timestamp(${physical}, { withTimezone: true, mode: "date" })`,
		};
		let builder = builders[column.columnType];
		if (!builder)
			throw new Error(`Unmapped column ${config.name}.${column.name}`);
		if ((column as { autoIncrement?: boolean }).autoIncrement)
			builder += ".generatedByDefaultAsIdentity()";
		if (column.primary) builder += ".primaryKey()";
		else if (column.notNull) builder += ".notNull()";
		if (column.isUnique) builder += ".unique()";
		if (column.default !== undefined) {
			if (is(column.default, SQL)) {
				let raw = dialect.sqlToQuery(column.default).sql;
				if (/randomblob/i.test(raw)) raw = "gen_random_uuid()::text";
				if (/datetime\('now'\)/i.test(raw)) raw = "CURRENT_TIMESTAMP";
				if (
					/current_timestamp/i.test(raw) &&
					column.columnType === "SQLiteText"
				)
					raw = `to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')`;
				builder += `.default(sql.raw(${JSON.stringify(raw)}))`;
			} else builder += `.default(${JSON.stringify(column.default)})`;
		}
		if (column.defaultFn) {
			const body = column.defaultFn.toString();
			if (
				!body.includes("crypto.randomUUID") &&
				!body.includes("new Date().toISOString")
			)
				throw new Error(`Review runtime default ${config.name}.${column.name}`);
			builder += `.$defaultFn(${body})`;
		}
		if (column.generated)
			review.push(
				`${config.name}.${column.name}: generated expression must be ported by its lane`,
			);
		lines.push(`${JSON.stringify(key)}: ${builder},`);
	}
	lines.push("}, (t) => [");
	for (const pk of config.primaryKeys)
		lines.push(
			`primaryKey({ columns: [${pk.columns.map((c) => `t[${JSON.stringify(keys.get(c.name))}]`).join(",")}]}),`,
		);
	for (const u of config.uniqueConstraints)
		lines.push(
			`uniqueIndex(${JSON.stringify(u.name)}).on(${u.columns.map((c) => `t[${JSON.stringify(keys.get(c.name))}]`).join(",")}),`,
		);
	for (const idx of config.indexes) {
		const c = idx.config;
		if (c.where || c.columns.some((column) => is(column, SQL))) {
			review.push(
				`${config.name}.${c.name}: expression or partial index must be ported by its lane`,
			);
			continue;
		}
		lines.push(
			`${c.unique ? "uniqueIndex" : "index"}(${JSON.stringify(c.name)}).on(${c.columns.map((column) => `t[${JSON.stringify(keys.get((column as { name: string }).name))}]`).join(",")}),`,
		);
	}
	for (const fk of config.foreignKeys) {
		const reference = fk.reference();
		const foreignName = getTableName(reference.foreignTable);
		if (!tables.some(([, table]) => getTableName(table) === foreignName))
			throw new Error(`Missing referenced table: ${foreignName}`);
		lines.push(
			`foreignKey({ name: ${JSON.stringify(fk.getName())}, columns: [${reference.columns.map((column) => `t[${JSON.stringify(keys.get(column.name))}]`).join(",")}], foreignColumns: [${reference.foreignColumns.map((column) => `referencedColumn(${JSON.stringify(foreignName)}, ${JSON.stringify(column.name)})`).join(",")}] }).onDelete(${JSON.stringify(fk.onDelete ?? "no action")}).onUpdate(${JSON.stringify(fk.onUpdate ?? "no action")}),`,
		);
	}
	for (const c of config.checks)
		review.push(`${config.name}.${c.name}: check must be ported by its lane`);
	lines.push("]);");
}
lines.push(
	`const tablesByName = new Map<string, PgTable>([${tables.map(([name]) => `[getTableName(${name}), ${name}]`).join(",")}]);`,
);
lines.push(`function referencedColumn(tableName: string, columnName: string): AnyPgColumn {
 const table = tablesByName.get(tableName);
 const column = table && Object.values(getColumns(table)).find(column => column.name === columnName);
 if (!column) throw new Error("Missing generated foreign key column: " + tableName + "." + columnName);
 return column;
}`);

writeFileSync(
	new URL("../src/schema-pg/core.ts", import.meta.url),
	lines.join("\n") + "\n",
);
writeFileSync(
	new URL("../src/schema-pg/review.json", import.meta.url),
	JSON.stringify(review, null, 2) + "\n",
);
console.log(
	`Generated ${tables.length} Postgres tables; ${review.length} lane-owned constraints/expressions need review.`,
);
